import{c as e,Q as a,j as o,m as d}from"./chunks/framework.DoOjWOm2.js";const b=JSON.parse('{"title":"Books Library Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"libraries/books.md","filePath":"libraries/books.md"}'),i={name:"libraries/books.md"};function r(s,t,n,l,c,h){return a(),o("div",null,[...t[0]||(t[0]=[d(`<h1 id="books-library-documentation" tabindex="-1">Books Library Documentation <a class="header-anchor" href="#books-library-documentation" aria-label="Permalink to &quot;Books Library Documentation&quot;">​</a></h1><p><strong>Since:</strong> 0.17.0</p><p>The books library provides support for electronic book formats (EPUB, PDF, CBZ) with OPDS 1.2 feed generation for third-party client compatibility.</p><h2 id="supported-formats" tabindex="-1">Supported Formats <a class="header-anchor" href="#supported-formats" aria-label="Permalink to &quot;Supported Formats&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Format</th><th>Extension</th><th>Metadata Extraction</th><th>Notes</th></tr></thead><tbody><tr><td>EPUB</td><td>epub</td><td>✅ Full</td><td>Parses content.opf for title, author, publisher, ISBN, language, publication date, description</td></tr><tr><td>PDF</td><td>pdf</td><td>✅ Basic</td><td>Uses exif_read_data for XMP/EXIF metadata; page count extraction</td></tr><tr><td>CBZ (Comic Book Archive)</td><td>cbz</td><td>✅ Full</td><td>Parses ComicInfo.xml for series, volume, author; extracts cover image</td></tr></tbody></table><h2 id="opds-feed-url" tabindex="-1">OPDS Feed URL <a class="header-anchor" href="#opds-feed-url" aria-label="Permalink to &quot;OPDS Feed URL&quot;">​</a></h2><p>The OPDS feed is available at <code>/opds/v1.2</code>. This follows the OPDS 1.2 specification and is compatible with:</p><ul><li><strong>Uboiquity</strong> (macOS/Windows/Linux)</li><li><strong>Komga</strong> (self-hosted)</li><li><strong>Kore</strong> (Android)</li><li><strong>Moon+ Reader</strong> (Android)</li><li><strong>Apple Books</strong> (iOS/macOS) — via third-party OPDS integration</li></ul><h2 id="opds-endpoints" tabindex="-1">OPDS Endpoints <a class="header-anchor" href="#opds-endpoints" aria-label="Permalink to &quot;OPDS Endpoints&quot;">​</a></h2><h3 id="root-feed" tabindex="-1">Root Feed <a class="header-anchor" href="#root-feed" aria-label="Permalink to &quot;Root Feed&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /opds/v1.2</span></span></code></pre></div><p>Returns the root OPDS catalog with links to libraries.</p><h3 id="libraries-navigation" tabindex="-1">Libraries Navigation <a class="header-anchor" href="#libraries-navigation" aria-label="Permalink to &quot;Libraries Navigation&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /opds/v1.2/libraries</span></span></code></pre></div><p>Returns a navigation feed listing all book libraries.</p><h3 id="library-acquisition-feed" tabindex="-1">Library Acquisition Feed <a class="header-anchor" href="#library-acquisition-feed" aria-label="Permalink to &quot;Library Acquisition Feed&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /opds/v1.2/libraries/{library_id}?offset=0&amp;limit=50</span></span></code></pre></div><p>Returns an acquisition feed listing all books in a library with pagination support.</p><h2 id="web-portal-endpoints" tabindex="-1">Web Portal Endpoints <a class="header-anchor" href="#web-portal-endpoints" aria-label="Permalink to &quot;Web Portal Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>/books</code></td><td>GET</td><td>List all books</td></tr><tr><td><code>/books/{id}</code></td><td>GET</td><td>Get book details</td></tr><tr><td><code>/books/{id}/cover</code></td><td>GET</td><td>Get cover image</td></tr><tr><td><code>/books/{id}/read</code></td><td>GET</td><td>Open reader stub</td></tr><tr><td><code>/books/{id}/download</code></td><td>GET</td><td>Download book file</td></tr></tbody></table><h2 id="naming-conventions" tabindex="-1">Naming Conventions <a class="header-anchor" href="#naming-conventions" aria-label="Permalink to &quot;Naming Conventions&quot;">​</a></h2><p>Books should be named to facilitate metadata extraction:</p><h3 id="epub" tabindex="-1">EPUB <a class="header-anchor" href="#epub" aria-label="Permalink to &quot;EPUB&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Author - Title.epub</span></span>
<span class="line"><span>Title (Year).epub</span></span></code></pre></div><h3 id="pdf" tabindex="-1">PDF <a class="header-anchor" href="#pdf" aria-label="Permalink to &quot;PDF&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Author - Title.pdf</span></span>
<span class="line"><span>Title.pdf</span></span></code></pre></div><h3 id="cbz-comics" tabindex="-1">CBZ (Comics) <a class="header-anchor" href="#cbz-comics" aria-label="Permalink to &quot;CBZ (Comics)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Series Name v01.cbz</span></span>
<span class="line"><span>Series Name 2020 Issue #01.cbz</span></span></code></pre></div><h2 id="metadata-fields-extracted" tabindex="-1">Metadata Fields Extracted <a class="header-anchor" href="#metadata-fields-extracted" aria-label="Permalink to &quot;Metadata Fields Extracted&quot;">​</a></h2><h3 id="epub-1" tabindex="-1">EPUB <a class="header-anchor" href="#epub-1" aria-label="Permalink to &quot;EPUB&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td>Book title from dc:title</td></tr><tr><td><code>author</code></td><td>Creator/author from dc:creator</td></tr><tr><td><code>publisher</code></td><td>Publisher from dc:publisher</td></tr><tr><td><code>isbn</code></td><td>ISBN from dc:identifier</td></tr><tr><td><code>language</code></td><td>Language code from dc:language</td></tr><tr><td><code>pub_date</code></td><td>Publication date from dc:date</td></tr><tr><td><code>description</code></td><td>Description from dc:description</td></tr><tr><td><code>cover_path</code></td><td>Path to extracted cover image</td></tr></tbody></table><h3 id="pdf-1" tabindex="-1">PDF <a class="header-anchor" href="#pdf-1" aria-label="Permalink to &quot;PDF&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td>Document title</td></tr><tr><td><code>author</code></td><td>Document author</td></tr><tr><td><code>subject</code></td><td>Document subject</td></tr><tr><td><code>keywords</code></td><td>Document keywords</td></tr><tr><td><code>creator</code></td><td>Creator application</td></tr><tr><td><code>producer</code></td><td>PDF producer</td></tr><tr><td><code>creation_date</code></td><td>Creation date</td></tr><tr><td><code>page_count</code></td><td>Number of pages</td></tr></tbody></table><h3 id="cbz" tabindex="-1">CBZ <a class="header-anchor" href="#cbz" aria-label="Permalink to &quot;CBZ&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td>Comic title</td></tr><tr><td><code>series</code></td><td>Series name</td></tr><tr><td><code>volume</code></td><td>Volume number</td></tr><tr><td><code>authors</code></td><td>Writer/artist names</td></tr><tr><td><code>page_count</code></td><td>Number of pages</td></tr><tr><td><code>cover_page</code></td><td>Cover page index</td></tr><tr><td><code>cover_path</code></td><td>Path to extracted cover</td></tr></tbody></table><h2 id="reader-stub" tabindex="-1">Reader Stub <a class="header-anchor" href="#reader-stub" aria-label="Permalink to &quot;Reader Stub&quot;">​</a></h2><p>The built-in reader stub at <code>/books/{id}/read</code> provides:</p><ul><li>Paginated HTML view (intentionally minimal)</li><li>Font size controls (A- / A+)</li><li>Theme switching (light / sepia / dark)</li><li>Keyboard navigation (← / →)</li></ul><p><strong>Note:</strong> Full EPUB rendering with text flow is planned for a future release. The current reader stub displays metadata and book information.</p><h2 id="third-party-opds-client-setup" tabindex="-1">Third-Party OPDS Client Setup <a class="header-anchor" href="#third-party-opds-client-setup" aria-label="Permalink to &quot;Third-Party OPDS Client Setup&quot;">​</a></h2><h3 id="uboiquity-recommended-for-desktop" tabindex="-1">Uboiquity (Recommended for desktop) <a class="header-anchor" href="#uboiquity-recommended-for-desktop" aria-label="Permalink to &quot;Uboiquity (Recommended for desktop)&quot;">​</a></h3><ol><li>File → Add Catalog</li><li>Enter OPDS feed URL: <code>http://your-server:8080/opds/v1.2</code></li><li>Browse and download books</li></ol><h3 id="komga" tabindex="-1">Komga <a class="header-anchor" href="#komga" aria-label="Permalink to &quot;Komga&quot;">​</a></h3><ol><li>Add server with your Phlix URL</li><li>Libraries are automatically discovered via OPDS</li></ol><h3 id="moon-reader" tabindex="-1">Moon+ Reader <a class="header-anchor" href="#moon-reader" aria-label="Permalink to &quot;Moon+ Reader&quot;">​</a></h3><ol><li>Menu → Online catalog</li><li>Add custom catalog</li><li>Enter OPDS feed URL</li></ol>`,46)])])}const u=e(i,[["render",r]]);export{b as __pageData,u as default};
